<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\CandidateProfile;use App\Models\Job;use App\Models\TalentInvitation;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class TalentPoolController extends Controller{public function preferences(Request $request):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);$data=$request->validate(['talent_visibility'=>['required',Rule::in(['hidden','verified_companies'])],'available_for_opportunities'=>['required','boolean']]);$profile=$request->user()->candidateProfile;abort_unless($profile,422);$profile->update($data);return response()->json(['data'=>$profile,'message'=>'Visibilidad actualizada.']);}public function search(Request $request):JsonResponse{$company=$this->company($request,true);abort_unless($company->verification_status==='verified',403,'Solo las empresas verificadas pueden buscar talento.');$query=CandidateProfile::with('user:id,name')->where('talent_visibility','verified_companies')->where('available_for_opportunities',true)->whereDoesntHave('user',fn($q)=>$q->whereHas('blockedCompanies',fn($b)=>$b->whereKey($company->id)));if($request->filled('q')){$term='%'.$request->string('q').'%';$query->where(fn($q)=>$q->where('professional_title','like',$term)->orWhere('summary','like',$term));}if($request->filled('province'))$query->where('province',$request->string('province'));return response()->json(['data'=>$query->paginate(20)->through(fn($p)=>['candidate_id'=>$p->user_id,'display_name'=>str($p->user->name)->before(' ').' '.str(str($p->user->name)->afterLast(' '))->substr(0,1).'.','professional_title'=>$p->professional_title,'province'=>$p->province,'skills'=>$p->skills,'availability'=>$p->availability])]);}public function save(Request $request,int $candidate):JsonResponse{$company=$this->company($request,true);$data=$request->validate(['list_name'=>['nullable','string','max:100'],'tags'=>['nullable','array','max:20'],'tags.*'=>['string','max:50']]);$profile=CandidateProfile::where('user_id',$candidate)->where('talent_visibility','verified_companies')->where('available_for_opportunities',true)->firstOrFail();DB::table('saved_talents')->updateOrInsert(['company_id'=>$company->id,'candidate_user_id'=>$profile->user_id],['saved_by'=>$request->user()->id,'list_name'=>$data['list_name']??'Favoritos','tags'=>json_encode($data['tags']??[]),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Talento guardado.']);}public function invite(Request $request,int $candidate):JsonResponse{$company=$this->company($request,true);$data=$request->validate(['job_id'=>['required','integer'],'message'=>['nullable','string','max:2000']]);$job=Job::whereKey($data['job_id'])->where('company_id',$company->id)->where('status','active')->firstOrFail();CandidateProfile::where('user_id',$candidate)->where('talent_visibility','verified_companies')->where('available_for_opportunities',true)->firstOrFail();abort_if(DB::table('blocked_companies')->where(['candidate_user_id'=>$candidate,'company_id'=>$company->id])->exists(),403);$invitation=TalentInvitation::firstOrCreate(['job_id'=>$job->id,'candidate_user_id'=>$candidate],['company_id'=>$company->id,'sent_by'=>$request->user()->id,'message'=>$data['message']??null]);return response()->json(['data'=>$invitation,'message'=>'Invitación enviada.'],201);}public function invitations(Request $request):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);return response()->json(['data'=>TalentInvitation::with('company:id,name','job:id,title,slug')->where('candidate_user_id',$request->user()->id)->latest()->get()]);}public function respond(Request $request,TalentInvitation $invitation):JsonResponse{abort_unless($invitation->candidate_user_id===$request->user()->id,404);$data=$request->validate(['response'=>['required',Rule::in(['accepted','declined'])]]);abort_unless($invitation->status==='pending',422);$invitation->update(['status'=>$data['response'],'responded_at'=>now()]);return response()->json(['data'=>$invitation,'message'=>'Respuesta registrada.']);}public function block(Request $request,int $company):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);DB::table('blocked_companies')->updateOrInsert(['candidate_user_id'=>$request->user()->id,'company_id'=>$company],['created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Empresa bloqueada.']);}private function company(Request $request,bool $write){abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422);if($write){$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;abort_unless(in_array($role,['owner','admin','recruiter']),403);}return $company;}}
